using Microsoft.EntityFrameworkCore;

namespace CosmosProject;

class CosmosDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        optionsBuilder.UseCosmos(
            "https://localhost:8081",
            "C2y6yDjf5/R+ob0N8A7Cgv30VRDJIWEHLM+4QDU5DE2nQ9nDuVTqobD4b8mGGyPMbIZnqyMsEcaGQy67XIw/Jw==",
            "CatalogDb");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 breaking change: The Cosmos provider now uses "$type" as the
        // discriminator property name by default instead of "Discriminator".
        // For existing documents that already store "Discriminator", you must
        // explicitly configure the old property name to avoid query failures.
        modelBuilder.Entity<Product>(b =>
        {
            b.ToContainer("Products");
            b.HasPartitionKey(p => p.Category);
            b.HasDiscriminator<string>("Discriminator");
        });
    }
}

class Product
{
    public string Id { get; set; } = default!;
    public string Name { get; set; } = default!;
    public string Category { get; set; } = default!;
}

using Microsoft.EntityFrameworkCore;

namespace CosmosProject;

class CosmosQueryService
{
    // EF Core 9 breaking change: Synchronous I/O is no longer supported by the
    // Cosmos DB provider. All queries must use async methods (ToListAsync,
    // FirstOrDefaultAsync, etc.) or a NotSupportedException is thrown at runtime.
    async Task<List<Product>> GetProductsByCategoryAsync(CosmosDbContext db, string category)
    {
        return await db.Products
            .Where(p => p.Category == category)
            .ToListAsync();
    }

    async Task<Product?> GetProductByIdAsync(CosmosDbContext db, string id)
    {
        return await db.Products.FirstOrDefaultAsync(p => p.Id == id);
    }
}

